#include <openssl/evp.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>
#include <stdint.h>

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9; }

int main(){
    size_t n = 40000*1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char *aad = malloc(32);
    unsigned char key[32]={0}, nonce[12]={0};
    memset(pt,0,n); memset(aad,0,32);
    int len=0;
    // raw chacha20
    {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        double t0=now();
        for(int i=0;i<5;i++){
            EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
            EVP_EncryptUpdate(ctx, ct, &len, pt, n);
            EVP_EncryptFinal_ex(ctx, ct+len, &len);
        }
        double t1=now();
        printf("chacha20 raw: %.4f s (%.2f GB/s)\n", (t1-t0)/5, n/((t1-t0)/5)/1e9);
        EVP_CIPHER_CTX_free(ctx);
    }
    // raw poly1305
    {
        EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
        unsigned char tag[16]; size_t taglen=16;
        double t0=now();
        for(int i=0;i<5;i++){
            EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
            EVP_MAC_init(mctx, key, 32, NULL);
            EVP_MAC_update(mctx, pt, n);
            EVP_MAC_final(mctx, tag, &taglen, 16);
            EVP_MAC_CTX_free(mctx);
        }
        double t1=now();
        printf("poly1305 raw: %.4f s (%.2f GB/s)\n", (t1-t0)/5, n/((t1-t0)/5)/1e9);
        EVP_MAC_free(mac);
    }
    return 0;
}
