{"command":"cd /private/var/folders/bd/8xxg4c4j4rqc_6fqwvpxwnd80000gn/T/algotuneprobe_x4rdcnxz/ep0 && cat > bench_par.c <<'EOF'
#include <openssl/evp.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9; }
#define T 12
typedef struct { unsigned char *pt; unsigned char *ct; size_t n; unsigned char key[32]; unsigned char nonce[12]; } job;
void* worker(void* a){
    job* j = (job*)a;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
    EVP_EncryptUpdate(ctx, j->ct, &len, j->pt, j->n);
    EVP_EncryptFinal_ex(ctx, j->ct+len, &len);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}
int main(){
    size_t n = 40000*1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    unsigned char key[32]={0}, nonce[12]={0};
    memset(pt,0,n);
    pthread_t th[T]; job jobs[T];
    size_t chunk = n/T;
    double t0=now();
    for(int i=0;i<T;i++){
        jobs[i].pt=pt+i*chunk; jobs[i].ct=ct+i*chunk; jobs[i].n=chunk;
        memcpy(jobs[i].key,key,32); memcpy(jobs[i].nonce,nonce,12);
        pthread_create(&th[i],NULL,worker,&jobs[i]);
    }
    for(int i=0;i<T;i++) pthread_join(th[i],NULL);
    double t1=now();
    printf("chacha20 par %d threads: %.4f s (%.2f GB/s)\n", T, t1-t0, n/(t1-t0)/1e9);
    return 0;
}
EOF
